    22→    repay_fee_rate: Decimal,
    23→
    24→    liquidation_fee_rate: Decimal,
    25→}
    26→
    27→public struct Asset<phantom MarketType> has key, store {
    28→    id: UID,
    29→    // Indicates when flash loan is in progress
    30→    flash_loan_lock: bool,
    31→    interest_model: InterestModel,
    32→    // dynamic fields:
    33→    // - borrow: Option<AssetConfig>
